'use client'

import { useEffect, useState } from 'react'
import { createBrowserClient } from '@supabase/ssr'
import { motion } from 'framer-motion'
import {
  FileText,
  Users,
  Bot,
  Target,
  Clock,
  Plus,
  ArrowRight,
  Sparkles,
  Brain,
  MoreVertical,
  Headphones,
  BookOpen as BookOpenIcon,
  Trash2,
  Bell,
  Scale,
  Calculator,
} from 'lucide-react'
import Link from 'next/link'
import { GlassCard } from '@/components/GlassCard'
import { ScrollFade } from '@/components/ScrollFade'
import { SupportChat } from '@/components/SupportChat'
import { StatCard } from '@/components/dashboard/StatCard'
import { TrendLineChart } from '@/components/dashboard/TrendLineChart'
import { PeriodoToggle } from '@/components/dashboard/PeriodoToggle'
import { MembroFiltro, MembroFiltroAviso } from '@/components/dashboard/MembroFiltro'
import { serieTemporal, type Periodo } from '@/lib/metrics/serie-temporal'

const supabase = createBrowserClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
)

interface Lawyer {
  id?: string
  name: string
  plan: string
  docs_limit: number
  docs_trial_used: number
  office_id?: string | null
}
interface Doc {
  id: string
  title?: string
  type?: string
  client_name?: string
  lawyer_id?: string
  created_at: string
}
interface Membro {
  id: string
  name: string
}
interface Notificacao {
  id: string
  title: string
  type?: string
  created_at: string
}

export default function Dashboard() {
  const [lawyer, setLawyer] = useState<Lawyer | null>(null)
  const [teamDocs, setTeamDocs] = useState<Doc[]>([])
  const [teamClients, setTeamClients] = useState<{ id: string; lawyer_id: string }[]>([])
  const [membros, setMembros] = useState<Membro[]>([])
  const [membroFiltro, setMembroFiltro] = useState<string>('todos')
  const [notificacoes, setNotificacoes] = useState<Notificacao[]>([])
  const [loading, setLoading] = useState(true)
  const [periodo, setPeriodo] = useState<Periodo>('semana')
  const [openSupport, setOpenSupport] = useState(false)
  const [isLight, setIsLight] = useState(false)
  useEffect(() => {
    const check = () => setIsLight(document.documentElement.classList.contains('light'))
    check()
    const observer = new MutationObserver(check)
    observer.observe(document.documentElement, { attributes: true, attributeFilter: ['class'] })
    return () => observer.disconnect()
  }, [])

  useEffect(() => {
    if (openSupport) {
      const t = setTimeout(() => setOpenSupport(false), 500)
      return () => clearTimeout(t)
    }
  }, [openSupport])

  useEffect(() => {
    async function load() {
      const { data: { user } } = await supabase.auth.getUser()
      if (!user) return
      const { data: l } = await supabase.from('lawyers').select('*').eq('id', user.id).single()
      setLawyer(l as Lawyer)

      let memberIds = [user.id]
      if (l?.office_id) {
        const { data: team } = await supabase
          .from('lawyers')
          .select('id, name')
          .eq('office_id', l.office_id)
          .order('name')
        if (team && team.length > 0) {
          setMembros(team as Membro[])
          memberIds = (team as Membro[]).map(m => m.id)
        }
      }

      const [{ data: d }, { data: c }, { data: n }] = await Promise.all([
        supabase.from('documents').select('*').in('lawyer_id', memberIds).order('created_at', { ascending: false }),
        supabase.from('clients').select('id, lawyer_id').in('lawyer_id', memberIds),
        supabase.from('notifications').select('*').eq('lawyer_id', user.id).order('created_at', { ascending: false }).limit(6),
      ])

      setTeamDocs((d as Doc[]) || [])
      setTeamClients((c as { id: string; lawyer_id: string }[]) || [])
      setNotificacoes((n as Notificacao[]) || [])
      setLoading(false)
    }
    load()
  }, [])

  async function apagarNotificacao(id: string) {
    setNotificacoes(prev => prev.filter(n => n.id !== id))
    await supabase.from('notifications').delete().eq('id', id)
  }

  const allDocs = membroFiltro === 'todos'
    ? teamDocs
    : teamDocs.filter(d => d.lawyer_id === membroFiltro)

  const clientCount = membroFiltro === 'todos'
    ? teamClients.length
    : teamClients.filter(c => c.lawyer_id === membroFiltro).length

  const docs = allDocs.slice(0, 5)

  const chartData = serieTemporal(allDocs.map(doc => doc.created_at), periodo)

  if (loading)
    return (
      <div className="min-h-[80vh] flex items-center justify-center">
        <div
          className="w-8 h-8 rounded-full border-2 animate-spin"
          style={{ borderColor: '#D4AF37', borderTopColor: 'transparent' }}
        />
      </div>
    )

  const docsUsed = lawyer?.docs_trial_used || 0
  const docsLimit = lawyer?.docs_limit || 5
  const firstName = lawyer?.name?.split(' ')[0] || 'Doutor'

  const totalDocs = allDocs.length
  const tempoEconomizado = Math.round(totalDocs * 1.5)

  const stats = [
    { icon: FileText, label: 'Peças Geradas', value: totalDocs, growth: totalDocs > 0 ? `${totalDocs} no total` : 'Comece agora', color: '#D4AF37' },
    { icon: Users, label: 'Clientes Ativos', value: clientCount, growth: clientCount > 0 ? `${clientCount} cadastrados` : 'Nenhum ainda', color: '#3B82F6' },
    { icon: Bot, label: 'Agentes IA Ativos', value: '200+', growth: '✓ Atualizados', color: '#A855F7' },
    { icon: Target, label: 'Precisão Jurídica', value: '99%', growth: '✓ Zero erros', color: '#22C55E' },
    { icon: Clock, label: 'Tempo Economizado', value: `${tempoEconomizado}h`, growth: totalDocs > 0 ? 'Baseado no uso' : 'Comece agora', color: '#F59E0B' },
  ]

  return (
    <div className="max-w-[1400px] mx-auto pb-6">
      {/* SAUDAÇÃO */}
      <motion.div
        initial={{ opacity: 0, y: 12 }}
        animate={{ opacity: 1, y: 0 }}
        className="mb-4 flex flex-wrap items-end justify-between gap-3"
      >
        <div>
          <h1 className="text-2xl font-black" style={{ color: isLight ? '#1E1E1E' : '#fff' }}>
            Olá, Dr. {firstName} 👋
          </h1>
          <p className="text-sm mt-0.5" style={{ color: isLight ? '#4F4F4F' : '#9ca3af' }}>
            Sua plataforma de inteligência jurídica previdenciária.
          </p>
        </div>

        <MembroFiltro
          membros={membros}
          value={membroFiltro}
          onChange={setMembroFiltro}
          isLight={isLight}
        />
      </motion.div>

      <MembroFiltroAviso membros={membros} value={membroFiltro} onChange={setMembroFiltro} />

      {/* FERRAMENTAS — ponto de entrada único para as ferramentas do dia a dia */}
      <motion.div
        initial={{ opacity: 0, y: 16 }}
        animate={{ opacity: 1, y: 0 }}
        className="mb-4"
      >
        <div className="px-1 mb-2 text-[10px] font-bold tracking-[0.2em]" style={{ color: isLight ? '#5E5E5E' : '#666' }}>
          FERRAMENTAS
        </div>
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-4">
          <Link href="/analise-previdenciaria" className="group lg:col-span-2 lg:row-span-2">
            <GlassCard gold intensity={0.6} style={{ padding: 24, height: '100%' }}>
              <div className="flex h-full flex-col">
                <div className="flex items-start gap-3 mb-3">
                  <div
                    className="w-12 h-12 rounded-2xl flex items-center justify-center flex-shrink-0"
                    style={{ background: 'rgba(212,175,55,0.15)', border: '1px solid rgba(212,175,55,0.3)' }}
                  >
                    <Scale size={22} color="#D4AF37" />
                  </div>
                  <div className="min-w-0">
                    <div className="flex items-center gap-2">
                      <h3 className="font-bold text-base" style={{ color: isLight ? '#1E1E1E' : '#fff' }}>
                        Análise Previdenciária
                      </h3>
                      <span
                        className="text-[8px] px-2 py-0.5 rounded-full font-bold tracking-wider"
                        style={{ background: 'rgba(212,175,55,0.2)', color: '#D4AF37' }}
                      >
                        DESTAQUE
                      </span>
                    </div>
                    <p className="text-xs mt-1" style={{ color: isLight ? '#5E5E5E' : '#9ca3af' }}>
                      Parecer técnico completo, histórico jurídico do cliente e análise de antecedentes.
                    </p>
                  </div>
                </div>
                <div className="flex flex-wrap gap-1.5 mb-4">
                  {['Parecer técnico', 'Histórico jurídico', 'Antecedentes'].map(tag => (
                    <span
                      key={tag}
                      className="text-[10px] px-2.5 py-1 rounded-lg"
                      style={{
                        background: isLight ? '#FFFFFF' : 'rgba(255,255,255,0.04)',
                        border: '1px solid rgba(212,175,55,0.18)',
                        color: isLight ? '#5E5E5E' : '#aaa',
                      }}
                    >
                      {tag}
                    </span>
                  ))}
                </div>
                <div className="mt-auto flex items-center gap-1.5 text-xs font-bold" style={{ color: '#D4AF37' }}>
                  Abrir análise
                  <ArrowRight size={14} className="transition-transform duration-200 group-hover:translate-x-1" />
                </div>
              </div>
            </GlassCard>
          </Link>

          {[
            { href: '/agentes', icon: Sparkles, label: 'Agentes IA', desc: 'Gerar peças com IA' },
            { href: '/ferramentas', icon: Calculator, label: 'Simulador & Cálculos', desc: 'Checklists e carências' },
            { href: '/jurisprudencia', icon: BookOpenIcon, label: 'Jurisprudência', desc: 'Banco de decisões' },
            { href: '/prazos', icon: Clock, label: 'Prazos', desc: 'Controle de vencimentos' },
          ].map(({ href, icon: Icon, label, desc }) => (
            <Link key={label} href={href} className="group">
              <GlassCard intensity={0.4} style={{ padding: 18, height: '100%' }}>
                <div className="flex h-full flex-col">
                  <div
                    className="w-9 h-9 rounded-xl flex items-center justify-center mb-3"
                    style={{ background: 'rgba(212,175,55,0.12)' }}
                  >
                    <Icon size={16} color="#D4AF37" />
                  </div>
                  <div className="text-xs font-bold mb-0.5" style={{ color: isLight ? '#1E1E1E' : '#fff' }}>
                    {label}
                  </div>
                  <div className="text-[10px]" style={{ color: isLight ? '#5E5E5E' : '#666' }}>
                    {desc}
                  </div>
                  <ArrowRight
                    size={13}
                    color="#555"
                    className="mt-auto self-end transition-transform duration-200 group-hover:translate-x-1"
                  />
                </div>
              </GlassCard>
            </Link>
          ))}
        </div>
      </motion.div>

      {/* LINHA 1: NOTIFICAÇÕES + AÇÕES RÁPIDAS */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
        >
          <GlassCard intensity={0.4} style={{ padding: 20, height: '100%' }}>
            <div className="flex items-center justify-between mb-3">
              <h3 className="font-bold text-white text-sm flex items-center gap-2">
                <Bell size={14} color="#D4AF37" /> Notificações
              </h3>
              {notificacoes.length > 0 && (
                <span className="text-[10px]" style={{ color: '#666' }}>
                  {notificacoes.length}
                </span>
              )}
            </div>
            <ScrollFade className="space-y-2 pr-0.5" style={{ maxHeight: 240 }} radius={12}>
              {notificacoes.length === 0 ? (
                <div className="text-center py-6 text-xs" style={{ color: '#666' }}>
                  Nenhuma notificação
                </div>
              ) : (
                notificacoes.map(n => {
                  const cor = n.type === 'success' ? '#22C55E' : n.type === 'warning' ? '#EF4444' : '#D4AF37'
                  return (
                    <div
                      key={n.id}
                      className="flex items-center gap-2.5 p-2 rounded-lg transition-colors group hover:bg-[rgba(212,175,55,0.05)]"
                    >
                      <div className="w-2 h-2 rounded-full flex-shrink-0" style={{ background: cor }} />
                      <span className="text-xs text-gray-300 flex-1 truncate">{n.title}</span>
                      <span className="text-[9px] text-gray-600 flex-shrink-0">
                        {new Date(n.created_at).toLocaleDateString('pt-BR')}
                      </span>
                      <button
                        type="button"
                        onClick={() => apagarNotificacao(n.id)}
                        className="opacity-0 group-hover:opacity-100 transition-opacity flex-shrink-0 p-1 rounded"
                        style={{ color: '#EF4444' }}
                        aria-label="Excluir notificação"
                        title="Excluir notificação"
                      >
                        <Trash2 size={12} />
                      </button>
                    </div>
                  )
                })
              )}
            </ScrollFade>
          </GlassCard>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
        >
          <GlassCard intensity={0.4} style={{ padding: 20, height: '100%' }}>
            <h3 className="font-bold text-white mb-4 text-sm">Ações Rápidas</h3>
            <div className="space-y-2">
              {[
                { href: '/agentes', icon: Plus, label: 'Novo Documento Rápido' },
                { href: '/agentes', icon: FileText, label: 'Petição Inicial' },
                { href: '/jurisprudencia', icon: BookOpenIcon, label: 'Consultar Jurisprudência' },
                { href: '/analise-previdenciaria', icon: Brain, label: 'Análise Previdenciária' },
              ].map(({ href, icon: Icon, label }, idx) => (
                <Link
                  key={idx}
                  href={href}
                  className="flex items-center gap-3 p-2.5 rounded-xl transition-all duration-200 hover:bg-white/5 group"
                  style={{ border: '1px solid rgba(255,255,255,0.05)' }}
                >
                  <div
                    className="w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0 transition-all group-hover:scale-110"
                    style={{ background: 'rgba(212,175,55,0.12)' }}
                  >
                    <Icon size={15} color="#D4AF37" />
                  </div>
                  <span className="text-xs font-medium text-white flex-1">{label}</span>
                  <ArrowRight
                    size={13}
                    color="#555"
                    className="group-hover:translate-x-1 transition-transform"
                  />
                </Link>
              ))}
            </div>
          </GlassCard>
        </motion.div>
      </div>

      {/* STATS */}
      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-4 mb-4">
        {stats.map((s, i) => (
          <StatCard
            key={s.label}
            index={i}
            icon={s.icon}
            label={s.label}
            value={s.value}
            growth={s.growth}
            color={s.color}
          />
        ))}
      </div>

      {/* LINHA 2: PRODUTIVIDADE (billing/analytics) + PLANO ATUAL */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4 mb-4">
        <motion.div
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          className="lg:col-span-2"
        >
          <GlassCard intensity={0.3} style={{ padding: 24, height: '100%' }}>
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-bold text-white">Produtividade Semanal</h3>
              <PeriodoToggle value={periodo} onChange={setPeriodo} />
            </div>
            <TrendLineChart data={chartData} />
            <div
              className="grid grid-cols-4 gap-3 mt-4 pt-4"
              style={{ borderTop: '1px solid rgba(255,255,255,0.06)' }}
            >
              {[
                { v: totalDocs.toString(), l: 'Total de Peças' },
                { v: totalDocs.toString(), l: 'Documentos' },
                { v: clientCount.toString(), l: 'Clientes' },
                { v: `${tempoEconomizado}h`, l: 'Tempo Economizado' },
              ].map(({ v, l }) => (
                <div key={l} className="text-center">
                  <div className="text-xl font-black text-gradient-gold">{v}</div>
                  <div className="text-[10px] text-gray-500">{l}</div>
                </div>
              ))}
            </div>
          </GlassCard>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          className="flex flex-col gap-4"
        >
          <GlassCard gold intensity={0.5} style={{ padding: 20, flex: 1 }}>
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-2">
                <Sparkles size={16} color="#D4AF37" />
                <h3 className="font-bold text-white text-sm">Plano Atual</h3>
              </div>
              <span
                className="text-[8px] px-2 py-0.5 rounded-full font-bold capitalize"
                style={{ background: 'rgba(212,175,55,0.2)', color: '#D4AF37' }}
              >
                {lawyer?.plan}
              </span>
            </div>
            <div className="font-bold text-white mb-0.5">Plano Profissional</div>
            <p className="text-[10px] text-gray-400 mb-3">
              Acesso completo a todos os recursos
            </p>
            <div className="flex justify-between text-[10px] mb-1.5">
              <span className="text-gray-400">Uso de documentos</span>
              <span className="text-white font-bold">
                {docsUsed} / {docsLimit}
              </span>
            </div>
            <div
              className="w-full h-2 rounded-full mb-3"
              style={{ background: 'rgba(255,255,255,0.06)' }}
            >
              <div
                className="h-full rounded-full"
                style={{
                  width: `${Math.min((docsUsed / docsLimit) * 100, 100)}%`,
                  background: 'linear-gradient(90deg, #D4AF37, #F0D060)',
                }}
              />
            </div>
            <div className="flex items-center justify-between">
              <span className="text-[10px] text-gray-500">Renova em 25 dias</span>
              <Link
                href="/assinatura"
                className="text-[10px] px-3 py-1.5 rounded-lg font-bold"
                style={{ background: 'rgba(212,175,55,0.15)', color: '#D4AF37' }}
              >
                Gerenciar Plano
              </Link>
            </div>
          </GlassCard>

          <GlassCard gold intensity={0.6} onClick={() => setOpenSupport(true)} style={{ padding: 16, cursor: 'pointer' }}>
            <div className="flex items-center gap-3">
              <div
                className="w-10 h-10 rounded-full flex items-center justify-center flex-shrink-0"
                style={{ background: 'rgba(212,175,55,0.15)' }}
              >
                <Headphones size={18} color="#D4AF37" />
              </div>
              <div className="flex-1">
                <div className="text-xs font-bold text-white">Precisa de ajuda?</div>
                <div className="text-[10px] text-gray-400">Fale com nosso suporte</div>
              </div>
            </div>
          </GlassCard>
        </motion.div>
      </div>

      {/* DOCUMENTOS RECENTES */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="mt-4"
      >
        <GlassCard intensity={0.3} style={{ padding: 24 }}>
          <div className="flex items-center justify-between mb-4">
            <h3 className="font-bold text-white">Documentos Recentes</h3>
            <Link
              href="/documentos"
              className="text-xs flex items-center gap-1"
              style={{ color: '#D4AF37' }}
            >
              Ver todos <ArrowRight size={13} />
            </Link>
          </div>
          {docs.length === 0 ? (
            <div className="space-y-2">
              {[
                {
                  t: 'Petição Inicial - Salário Maternidade Rural',
                  c: 'Maria do Socorro Silva Costa',
                  d: '25/02/2026',
                },
                {
                  t: 'Requerimento - Aposentadoria por Idade',
                  c: 'João Pereira da Silva',
                  d: '24/02/2026',
                },
                {
                  t: 'Apelação - Benefício por Incapacidade',
                  c: 'Antônia Clara dos Santos',
                  d: '23/02/2026',
                },
              ].map((doc, i) => (
                <div
                  key={i}
                  className="flex items-center gap-3 p-3 rounded-xl transition-all duration-200 hover:bg-white/5"
                  style={{ border: '1px solid rgba(255,255,255,0.05)' }}
                >
                  <div
                    className="w-9 h-9 rounded-lg flex items-center justify-center flex-shrink-0"
                    style={{ background: 'rgba(212,175,55,0.12)' }}
                  >
                    <FileText size={15} color="#D4AF37" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="text-sm font-medium text-white truncate">{doc.t}</div>
                    <div className="text-[11px] text-gray-500">{doc.c}</div>
                  </div>
                  <span className="text-[11px] text-gray-500">{doc.d}</span>
                  <MoreVertical size={14} color="#555" />
                </div>
              ))}
            </div>
          ) : (
            <div className="space-y-2">
              {docs.map((d, i) => (
                <div
                  key={d.id || i}
                  className="flex items-center gap-3 p-3 rounded-xl transition-all duration-200 hover:bg-white/5"
                  style={{ border: '1px solid rgba(255,255,255,0.05)' }}
                >
                  <div
                    className="w-9 h-9 rounded-lg flex items-center justify-center flex-shrink-0"
                    style={{ background: 'rgba(212,175,55,0.12)' }}
                  >
                    <FileText size={15} color="#D4AF37" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="text-sm font-medium text-white truncate">
                      {d.title || d.type || 'Petição'}
                    </div>
                    <div className="text-[11px] text-gray-500">
                      {d.client_name || 'Cliente'}
                    </div>
                  </div>
                  <span className="text-[11px] text-gray-500">
                    {new Date(d.created_at).toLocaleDateString('pt-BR')}
                  </span>
                  <MoreVertical size={14} color="#555" />
                </div>
              ))}
            </div>
          )}
        </GlassCard>
      </motion.div>

      {/* RODAPÉ */}
      <div
        className="text-center mt-6 flex items-center justify-center gap-2 text-[11px]"
        style={{ color: '#555' }}
      >
        <span className="text-gradient-gold font-bold">MARPLE</span> · Inteligência Jurídica
        que transforma resultados. · 🔒 Segurança de nível bancário
      </div>
      <SupportChat defaultOpen={openSupport}/>
    </div>
  )
}
